# --- Engineered physiological features (computed in build_engineered) ----------
HRR = "HRR_pct"              # % heart-rate reserve — relative exercise intensity
KCAL_MIN = "Kcal_per_min"    # calorie burn rate — session density
WEEKLY_VOL = "Weekly_Volume_hrs"  # hours trained per week — training load

ALL_NUMERIC = [AGE, WEIGHT, HEIGHT, MAX_BPM, AVG_BPM, RESTING_BPM, SESSION,
               CALORIES, FAT, WATER, FREQ, EXP, BMI]
ENGINEERED = [HRR, KCAL_MIN, WEEKLY_VOL]


def build_engineered(df: pd.DataFrame) -> pd.DataFrame:
    """Add physiologically-grounded features derived from raw columns.

    * ``HRR_pct``  — % of heart-rate reserve actually used
      (Avg_BPM − Resting_BPM) / (Max_BPM − Resting_BPM). The standard sports-
      science measure of *relative* intensity, comparable across ages — unlike
      raw BPM, which declines with age.
    * ``Kcal_per_min`` — Calories_Burned / session minutes. How densely a
      member burns energy per minute, independent of session length.
    * ``Weekly_Volume_hrs`` — session length × sessions/week. Total weekly
      training load.
    """
    out = df.copy()
    reserve = (out[MAX_BPM] - out[RESTING_BPM]).clip(lower=1)
    out[HRR] = (out[AVG_BPM] - out[RESTING_BPM]) / reserve * 100
    out[KCAL_MIN] = out[CALORIES] / (out[SESSION] * 60)
    out[WEEKLY_VOL] = out[SESSION] * out[FREQ]
    return out

# Curated set: drops the near-duplicates (Weight≈BMI, Session≈Calories,
