def name_personas(df_clustered: pd.DataFrame, features: list[str]) -> dict:
    """Return {cluster_id: (name, description, dominant_workout)}.

    Naming always uses :data:`NAMING_FEATURES` (intersected with what's in the
    frame) so persona labels are stable and physiologically meaningful even
    when the modelling feature set is minimal.
    """
    naming = [f for f in NAMING_FEATURES if f in df_clustered.columns]
    profile = profile_table(df_clustered, naming)
    z = zscores(profile, naming)
    out = {}
    for cid in profile.index:
        sub = df_clustered[df_clustered["cluster"] == cid]
        dominant = sub[WORKOUT].mode().iloc[0] if len(sub) else "—"
        out[cid] = (persona_name(z.loc[cid], dominant),
                    persona_description(z.loc[cid]), dominant)

    # Uniquify: duplicate names get a qualifier from their most extreme
    # deviation, e.g. "Casual Beginner · High Fat_Percentage".
    counts = Counter(name for name, _, _ in out.values())
    for cid, (name, desc, dominant) in list(out.items()):
        if counts[name] > 1:
            zrow = z.loc[cid]
            f = zrow.abs().idxmax()
            qual = ("High " if zrow[f] > 0 else "Low ") + f
            out[cid] = (f"{name} · {qual}", desc, dominant)
    seen = Counter()
    for cid, (name, desc, dominant) in list(out.items()):
        seen[name] += 1
        if seen[name] > 1:
            out[cid] = (f"{name} {'I' * seen[name]}", desc, dominant)
    return out


# --- Shared plot helpers --------------------------------------------------------

def silhouette_plot(X: np.ndarray, labels: np.ndarray, height: int = 380):
    """Per-sample silhouette plot (one filled band per cluster)."""
    samples = silhouette_samples(X, labels)
    fig = go.Figure()
    y0 = 10
    for cid in sorted(set(labels)):
        vals = np.sort(samples[labels == cid])
        y1 = y0 + len(vals)
        fig.add_trace(go.Scatter(
            x=np.concatenate([vals, vals[::-1]]),
            y=np.concatenate([np.full_like(vals, y0, dtype=float),
                              np.full_like(vals, y1, dtype=float)]),
            fill="toself", mode="lines",
            line=dict(color=CLUSTER_COLORS[cid % len(CLUSTER_COLORS)], width=0),
            fillcolor=CLUSTER_COLORS[cid % len(CLUSTER_COLORS)],
            name=f"Cluster {cid} (n={len(vals)})",
        ))
        y0 = y1 + 10
    avg = samples.mean()
    fig.add_vline(x=avg, line_color=theme.PALETTE["bad"], line_dash="dash",
                  annotation_text=f"avg = {avg:.3f}")
    fig.update_layout(title="Silhouette plot — per-sample cohesion vs separation",
                      xaxis_title="Silhouette coefficient", yaxis_title="Samples")
    return theme.style_fig(fig, height)


def pca_scatter(X: np.ndarray, labels: np.ndarray, n_comp: int = 2,
                height: int = 420):
    pca = PCA(n_components=n_comp, random_state=42)
    Z = pca.fit_transform(X)
    dfp = pd.DataFrame(Z, columns=[f"PC{i+1}" for i in range(n_comp)])
    dfp["cluster"] = labels.astype(str)
    kwargs = dict(color="cluster", color_discrete_sequence=CLUSTER_COLORS,
                  opacity=0.75, title=f"PCA projection ({n_comp}D) — "
                  f"{pca.explained_variance_ratio_.sum():.0%} variance explained")
    if n_comp == 3:
        fig = px.scatter_3d(dfp, x="PC1", y="PC2", z="PC3", **kwargs)
    else:
        fig = px.scatter(dfp, x="PC1", y="PC2", **kwargs)
    return theme.style_fig(fig, height), pca


